"""Render bench/results/*.json into bench/results/summary.md (generated; do not edit by hand).

Usage: .venv-pyin/bin/python -m jamrecall_bench.report
"""

from __future__ import annotations

from jamrecall_bench.common import RESULTS, read_json

LABELS = {
    "pyin": "pYIN + onset segmentation (librosa)",
    "basic-pitch": "Basic Pitch (ONNX), mono post-process",
    "basic-pitch-raw": "Basic Pitch (ONNX), raw polyphonic",
    "fixture": "TEST-ONLY fixture (ignores audio)",
}


def load():
    rows = {}
    for m in ("pyin", "basic-pitch", "fixture"):
        p = RESULTS / f"{m}.json"
        if not p.exists():
            continue
        r = read_json(p)
        rows[m] = r
        if m == "basic-pitch" and "results_raw_polyphonic" in r:
            rows["basic-pitch-raw"] = r | {"results": r["results_raw_polyphonic"]}
    return rows


def fmt(x, pct=False):
    if x is None:
        return "–"
    return f"{100 * x:.1f}%" if pct else f"{x:.3f}"


def main_table(rows, split):
    out = [
        f"| Method | GuitarSet {split} onset P / R / **F1** | +offset F1 "
        f"| median abs onset err (ms) "
        f"| pitch exact / octave err (onset-matched) | Synthetic {split} onset F1 | +offset F1 |",
        "|---|---|---|---|---|---|---|",
    ]
    for m, r in rows.items():
        g, s = r["results"][f"guitarset/{split}"], r["results"][f"synthetic/{split}"]
        pe = g["pitch_on_onset_matched"]
        out.append(
            f"| {LABELS[m]} | {fmt(g['onset']['precision'])} / {fmt(g['onset']['recall'])} / "
            f"**{fmt(g['onset']['f1'])}** | {fmt(g['onset_offset']['f1'])} | "
            f"{g['onset_error_ms']['median_abs'] or '–'} | "
            f"{fmt(pe['exact'], True)} / {fmt(pe['octave'], True)} | "
            f"{fmt(s['onset']['f1'])} | {fmt(s['onset_offset']['f1'])} |"
        )
    return "\n".join(out)


def tag_table(rows, key, prefix):
    methods = [m for m in rows if m != "fixture"]
    tags = sorted({t for m in methods for t in rows[m]["results"][key]["by_tag"]
                   if t.startswith(prefix)})
    out = ["| " + prefix.rstrip("=") + " | notes | " + " | ".join(LABELS[m] for m in methods)
           + " |", "|---|---|" + "---|" * len(methods)]
    for t in tags:
        n = rows[methods[0]]["results"][key]["by_tag"][t]["n_ref"]
        out.append(f"| {t.split('=', 1)[1]} | {n} | " + " | ".join(
            fmt(rows[m]["results"][key]["by_tag"][t]["f1"]) for m in methods) + " |")
    return "\n".join(out)


def profile_table():
    out = ["| Method | import + model load (s) | first call (s / audio s) | warm real-time factor "
           "| CPU-s per wall-s | peak RSS (MB) |", "|---|---|---|---|---|---|"]
    for m in ("pyin", "basic-pitch"):
        p = RESULTS / f"profile-{m}.json"
        if not p.exists():
            continue
        r = read_json(p)
        out.append(
            f"| {LABELS[m]} | {r['import_and_model_load_s']} | {r['first_call']['latency_s']} / "
            f"{r['first_call']['audio_s']} | {r['warm']['real_time_factor']} | "
            f"{r['warm']['cpu_s_per_wall_s']} | {r['peak_rss_mb']} |"
        )
    return "\n".join(out)


def main() -> None:
    rows = load()
    parts = [
        "# Benchmark summary (generated by `jamrecall_bench.report`)",
        "",
        "Tolerances: onset ±50 ms, pitch ±50 cents; offset-aware F1 additionally requires offset "
        "within max(50 ms, 20% of note). Micro-averaged over notes. Parameters chosen by onset F1 "
        "on GuitarSet dev only.",
        "",
        "## Holdout (players 03–05; synthetic holdout seeds/transpositions)",
        main_table(rows, "holdout"),
        "",
        "## Dev (used for parameter selection)",
        main_table(rows, "dev"),
        "",
        "## Synthetic holdout by condition (onset F1)",
        tag_table(rows, "synthetic/holdout", "condition="),
        "",
        "## Synthetic holdout by phrase type (onset F1)",
        tag_table(rows, "synthetic/holdout", "phrase="),
        "",
        "## Synthetic holdout by tempo (onset F1)",
        tag_table(rows, "synthetic/holdout", "bpm="),
        "",
        "## GuitarSet holdout by style (onset F1)",
        tag_table(rows, "guitarset/holdout", "style="),
        "",
        "## Runtime and memory (fresh process, whole GuitarSet holdout solo files)",
        profile_table(),
        "",
        "## Selected parameters",
    ]
    for m, r in rows.items():
        if m != "basic-pitch-raw":
            parts.append(f"- {LABELS[m]}: `{r['selected_params']}`")
    env = next(iter(rows.values()))["environment"]
    parts += ["", f"Environment: Python {env['python']}, {env['platform']}."]
    (RESULTS / "summary.md").write_text("\n".join(parts) + "\n")
    print((RESULTS / "summary.md").read_text())


if __name__ == "__main__":
    main()
